#include "seidel-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization, translated to Halide.
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
 *
 * Mapping to Halide:
 *   - C: A[i][j]  -> Halide Buffer: A(j, i)
 *   - i is the row index (outer loop) -> Var y
 *   - j is the column index (inner loop) -> Var x
 */
static void
init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var x("x"), y("y");
    Func init_A("init_A");

    // A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
    // Map (i, j) -> (y, x), and write init_A(x, y).
    init_A(x, y) =
        (cast<num_t>(y * (x + 2) + 2) /
         cast<num_t>(n));

    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int tsteps = TSTEPS;

    // Buffers for the solution.
    // C array: DATA_TYPE A[N][N]  ->  Halide Buffer: A(x, y) with shape (n, n)
    Buffer<num_t, 2> A(n, n);
    Buffer<num_t, 2> B(n, n);  // scratch buffer for time-stepping (double buffering)

    // Initialize A
    init_array(n, A);

    // Halide representation of one Seidel time step.
    //
    // Original kernel:
    //
    // for (t = 0; t <= _PB_TSTEPS - 1; t++)
    //   for (i = 1; i <= _PB_N - 2; i++)
    //     for (j = 1; j <= _PB_N - 2; j++)
    //       A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
    //                + A[i][j-1]   + A[i][j]   + A[i][j+1]
    //                + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1]) / 9.0;
    //
    // Notes for the Halide translation:
    //   - This is a time-stepped stencil with loop-carried dependence in A.
    //   - We follow the recommended pattern (Rule 5): define a single-step
    //     transform that reads from an ImageParam (previous time step) and
    //     write the result into a separate Buffer, using a host-side loop
    //     over t with double buffering.
    //   - Boundaries i = 0, n-1, j = 0, n-1 are never updated in the C code;
    //     they keep their previous values. We reproduce that via a select()
    //     that copies the old value outside the interior region.
    //   - To satisfy Halide bounds inference (Rule 7), we wrap the input
    //     with BoundaryConditions::repeat_edge so that neighbor accesses
    //     are always in-bounds, even though they are only used for interior
    //     points.

    // Parameters for the step.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    Param<int> n_param("n_param");

    Var x("x"), y("y");

    // Wrap the input in a boundary condition to avoid out-of-bounds reads.
    // A_param is 2D; repeat_edge will clamp coordinates to the valid extent.
    Func padded = Halide::BoundaryConditions::repeat_edge(A_param);

    Func seidel_step("seidel_step");

    Expr interior =
        (x >= 1) && (x <= n_param - 2) &&
        (y >= 1) && (y <= n_param - 2);

    Expr sum_neighbors =
        padded(x - 1, y - 1) + padded(x - 1, y) + padded(x - 1, y + 1) +
        padded(x,     y - 1) + padded(x,     y) + padded(x,     y + 1) +
        padded(x + 1, y - 1) + padded(x + 1, y) + padded(x + 1, y + 1);

    Expr avg = sum_neighbors / cast<num_t>(Expr(9.0));

    // For interior points, use the 3x3 average; for boundary points, keep old value.
    seidel_step(x, y) = select(interior, avg, A_param(x, y));

    // The default schedule is fine here; it corresponds to:
    //   for (y) for (x) seidel_step(x, y) = ...
    // which matches the i/j nesting order in the original C code
    // (i is y / row index, j is x / column index).
    // We don't need any explicit scheduling beyond this.

    // Bind the parameters and JIT-compile once.
    A_param.set(A);
    n_param.set(n);
    seidel_step.compile_jit();

    // Measure only the time-stepping computation, as in the gemm example.
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // Current state is in A; next state will go into B.
        A_param.set(A);
        n_param.set(n);

        seidel_step.realize(B);

        // Swap A and B for the next time step.
        std::swap(A, B);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results to prevent dead-code elimination, similar to print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Original C indexing: A[i][j]  ->  Halide: A(j, i)
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
