#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// Common PolyBench-style defines (DATA_TYPE, N, TSTEPS, etc.)
#include "defines.hpp"

// Benchmark-specific defines (N, TSTEPS, SCALAR_VAL, etc.)
#include "seidel-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize A exactly like the C version:
//
// for (i = 0; i < n; i++)
//   for (j = 0; j < n; j++)
//     A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
//
// C array A[i][j] maps to Buffer A(j, i) (x=j, y=i).
static void init_array(int n, Buffer<num_t, 2> A) {
    Var i("i"), j("j");
    Func init_A("init_A");

    // j is the x coordinate (column), i is the y coordinate (row).
    init_A(j, i) = cast<num_t>(i * (j + 2) + 2) / cast<int>(n);

    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // State buffers: A holds the current time step, B the next.
    // Dimension 0: x (j), dimension 1: y (i)
    Buffer<num_t, 2> A(n, n);
    Buffer<num_t, 2> B(n, n);

    // Initialize A
    init_array(n, A);

    // ImageParam that will refer to the "current" state each iteration
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Vars for the spatial coordinates
    Var x("x"), y("y");

    // Single time-step update: from A_param -> step
    //
    // The original C kernel is in-place Gauss-Seidel:
    //
    // for (t = 0; t <= tsteps-1; t++)
    //   for (i = 1; i <= n-2; i++)
    //     for (j = 1; j <= n-2; j++)
    //       A[i][j] = (sum of 3x3 neighbors)/9;
    //
    // In Halide, we avoid illegal self-referential updates by doing
    // a Jacobi-style step: read from A_param, write into a separate
    // buffer B, and iterate on the host (double buffering).
    //
    // We wrap A_param in a boundary condition so that bounds inference
    // is satisfied even though we access neighbors x±1, y±1.
    Func A_bc = BoundaryConditions::repeat_edge(A_param);

    Func step("seidel_step");

    Expr width  = A_param.width();   // extent in x
    Expr height = A_param.height();  // extent in y

    // True for boundary pixels (0 and n-1 in each dimension)
    Expr is_boundary =
        (x == 0) || (x == width - 1) ||
        (y == 0) || (y == height - 1);

    // 3x3 average of neighbors (including center) from the previous state
    Expr sum_neighbors =
          A_bc(x - 1, y - 1) + A_bc(x - 1, y    ) + A_bc(x - 1, y + 1)
        + A_bc(x    , y - 1) + A_bc(x    , y    ) + A_bc(x    , y + 1)
        + A_bc(x + 1, y - 1) + A_bc(x + 1, y    ) + A_bc(x + 1, y + 1);

    Expr avg_neighbors = sum_neighbors / Expr(9.0);

    // Interior: apply 3x3 average
    // Boundary: keep the same value as previous state
    step(x, y) = select(is_boundary, A_bc(x, y), avg_neighbors);

    // Simple schedule: row-major traversal, vectorize in x, parallelize in y.
    step.vectorize(x, 8).parallel(y);

    // Compile the single-step pipeline to machine code
    step.compile_jit();

    // Time the full tsteps iterations
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // Bind the current state to the ImageParam
        A_param.set(A);

        // Compute the next state into B
        step.realize(B);

        // Swap A and B (double buffering)
        std::swap(A, B);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the final array (to defeat dead-code elimination),
    // similar in spirit to the PolyBench print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A(j, i): x=j, y=i
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
