#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, TSTEPS, etc)
#include "defines.hpp"

// include benchmark-specific definitions for seidel-2d
#include "seidel-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization: corresponds to the C init_array().
 *
 * C code:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
 *
 * In C, A is declared as DATA_TYPE A[N][N] and accessed as A[i][j].
 * In Halide::Buffer, we store A with x = column = j (fastest-varying),
 * y = row = i (slowest-varying), so we access as A(j, i).
 */
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");
    Func init_A("init_A");

    // init_A(j, i) corresponds to A[i][j] in the C code
    init_A(j, i) = cast<num_t>(i * (j + 2) + 2) / Expr(n);

    // Realize directly into the provided Buffer
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size and time steps from PolyBench (see seidel-2d.hpp / defines.hpp)
    int n = N;
    int tsteps = TSTEPS;

    // Buffers to hold the grid; we will double-buffer between time steps.
    // As per Rule 1, for A[n][n] we use Buffer(n, n) and index as A(x=j, y=i).
    Halide::Buffer<num_t, 2> A_cur(n, n);
    Halide::Buffer<num_t, 2> A_next(n, n);

    // Initialize A_cur with the same semantics as the original C version.
    init_array(n, A_cur);

    // ------------------------------------------------------------------------
    // Halide pipeline for a SINGLE time step of the Seidel-like stencil.
    //
    // Original C kernel (per time step):
    //
    // for (i = 1; i <= n-2; i++)
    //   for (j = 1; j <= n-2; j++)
    //     A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
    //                + A[i][j-1]   + A[i][j]   + A[i][j+1]
    //                + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1]) / 9.0;
    //
    // We express a *single* update step as a Halide Func "step", which reads
    // from an ImageParam "A_param" representing the current grid, and produces
    // the updated grid in a new Buffer. Time-stepping (loop over t) is done
    // on the host via double-buffering (see Rule 5).
    // ------------------------------------------------------------------------

    Var x("x"), y("y");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    Func step("seidel_step");

    // Pure definition: by default, copy the current state.
    step(x, y) = A_param(x, y);

    // Update definition: overwrite the interior points (1..n-2) with the
    // 3x3 stencil average over the current state A_param.
    //
    // We use the extents of A_param at runtime to define the reduction domain.
    Expr width  = A_param.dim(0).extent();  // extent in x (columns)
    Expr height = A_param.dim(1).extent();  // extent in y (rows)

    RDom r(1, width - 2,
           1, height - 2,
           "r");

    Expr sum =
        A_param(r.x - 1, r.y - 1) + A_param(r.x,     r.y - 1) + A_param(r.x + 1, r.y - 1) +
        A_param(r.x - 1, r.y    ) + A_param(r.x,     r.y    ) + A_param(r.x + 1, r.y    ) +
        A_param(r.x - 1, r.y + 1) + A_param(r.x,     r.y + 1) + A_param(r.x + 1, r.y + 1);

    // Use integer literal 9; Halide's type promotion rules will keep the
    // expression in the same floating type as A_param.
    step(r.x, r.y) = sum / 9;

    // Simple schedule that preserves row-major traversal semantics:
    // - y is the outer loop (rows, i)
    // - x is the inner loop (columns, j)
    // This matches the original C nesting order.
    step.compute_root();
    // The default ordering already gives y outer, x inner; explicit
    // reorders are not strictly necessary here.

    // JIT-compile the single-step stencil once before timing.
    step.compile_jit();

    // ------------------------------------------------------------------------
    // Time-stepping loop on the host (double buffering).
    // Each iteration applies one stencil step to the entire grid.
    // ------------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // Bind the current grid to the ImageParam
        A_param.set(A_cur);

        // Compute the next grid into A_next
        step.realize(A_next);

        // Swap current and next for the next iteration
        A_cur.swap(A_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ------------------------------------------------------------------------
    // Optional: print the resulting array to stderr (one value per line),
    // similar in spirit to PolyBench's print_array. This matches the style
    // used in example/gemm.cpp.
    // ------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Recall: Buffer is indexed as (x=j, y=i)
                std::cerr << A_cur(j, i) << '\n';
            }
        }
    }

    // Print the elapsed time in seconds to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
