#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// -----------------------------------------------------------------------------
// Problem parameters (mirroring the PolyBench seidel-2d benchmark)
// -----------------------------------------------------------------------------

// Grid size
#ifndef N
#define N 4000
#endif

// Number of time steps
#ifndef TSTEPS
#define TSTEPS 100
#endif

// Scalar type used in the original benchmark
using num_t = double;

using namespace Halide;

// -----------------------------------------------------------------------------
// Initialization kernel (Halide version of init_array)
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // C code:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
    //
    // Mapping to Halide:
    //   C indices A[i][j]  ->  Halide A(j, i)
    //   Buffer shape       ->  (n, n)

    Var i("i"), j("j");
    Func init("init");

    // Note: i and j are Int(32); we cast the expression to num_t,
    // and divide by num_t(n) to match the original floating-point math.
    init(j, i) = cast<num_t>(i * (j + 2) + 2) / Expr((num_t)n);

    init.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size (match the original C code)
    int n = N;
    int tsteps = TSTEPS;

    // Allocate the 2D array A as a Halide buffer.
    // C: DATA_TYPE A[N][N];
    // Halide: Buffer<num_t,2> A(width = n, height = n);
    // Access: A(j, i) corresponds to C's A[i][j].
    Buffer<num_t, 2> A(n, n);

    // Initialize A
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Build the Halide pipeline for a single Seidel/Jacobi time step
    //
    // Original C kernel (per time step):
    //
    // for (i = 1; i <= n-2; i++)
    //   for (j = 1; j <= n-2; j++)
    //     A[i][j] = (A[i-1][j-1] + A[i-1][j]   + A[i-1][j+1]
    //               + A[i  ][j-1] + A[i  ][j] + A[i  ][j+1]
    //               + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1]) / 9.0;
    //
    // Halide cannot express this in-place Gauss-Seidel update directly
    // (because it reads and writes the same array with different indices).
    //
    // Instead, we express a *single* time-step as a pure transform:
    //
    //   output(i, j) = input(i, j)           for boundary points
    //   output(i, j) = stencil(input, i, j)  for interior points
    //
    // and iterate this transform on the host using double-buffering.
    //
    // This corresponds to a Jacobi-style iteration that is close in
    // spirit to the original Seidel scheme.
    // -------------------------------------------------------------------------

    // Input image for the step kernel
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Runtime parameter for the spatial size n
    Param<int> n_param("n");

    // Vars
    Var i("i"), j("j");

    // Single-step stencil
    Func seidel_step("seidel_step");

    // Start with the previous state everywhere
    seidel_step(j, i) = A_param(j, i);

    // Update the interior points [1 .. n-2] x [1 .. n-2]
    RDom r(1, n_param - 2,
           1, n_param - 2, "r");

    Expr sum =
        A_param(r.x - 1, r.y - 1) +
        A_param(r.x - 1, r.y    ) +
        A_param(r.x - 1, r.y + 1) +
        A_param(r.x,     r.y - 1) +
        A_param(r.x,     r.y    ) +
        A_param(r.x,     r.y + 1) +
        A_param(r.x + 1, r.y - 1) +
        A_param(r.x + 1, r.y    ) +
        A_param(r.x + 1, r.y + 1);

    seidel_step(r.x, r.y) = sum / Expr((num_t)9.0);

    // Optional: make the j (column) coordinate the innermost loop
    seidel_step.reorder(j, i);
    seidel_step.update().reorder(r.x, r.y);  // r.y (i) outer, r.x (j) inner

    // Bind runtime parameters and JIT-compile once
    A_param.set(A);
    n_param.set(n);

    seidel_step.compile_jit();

    // Double buffer: A holds the current state, B will hold the next state
    Buffer<num_t, 2> B(n, n);

    // -------------------------------------------------------------------------
    // Run the time-stepping loop and measure its execution time
    // -------------------------------------------------------------------------
    using clock_type = std::chrono::high_resolution_clock;

    auto start = clock_type::now();

    for (int t = 0; t < tsteps; t++) {
        // Bind the current buffer as input
        A_param.set(A);
        n_param.set(n);

        // Compute the next time step
        seidel_step.realize(B);

        // Swap A and B so that A always holds the latest state
        std::swap(A, B);
    }

    auto end = clock_type::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optionally dump the result (similar spirit to print_array)
    // -------------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_idx = 0; i_idx < n; i_idx++) {
            for (int j_idx = 0; j_idx < n; j_idx++) {
                // A(j, i) corresponds to A[i][j] in the original C code
                std::cerr << A(j_idx, i_idx) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
